use crate::LayoutMutation;
use semio_s_artifact_layout_layout_model::snapshot::LayoutSnapshot;
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneRef,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits}};
use semio_s_artifact_layout_layout_mutations_decisions::simple::*;

fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn decode<T:semio_framework_value::FromValue>(v:&serde_json::Value)->T{semio_framework_pack_json::from_json_str(&v.to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
#[test]
fn preexisting_neutral_semantic_witnesses_admit_without_cold_leaf_execution(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../../../🧪️tests/🧫️fixtures/⚙️semantic/🔣️.json")).unwrap();let extra:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let mut checked=0;for row in corpus["cases"].as_array().unwrap().iter().chain(extra["commands"].as_array().unwrap()){let mutation:LayoutMutation=decode(&row["mutation"]);if SimpleKind::of(&mutation).is_none()||matches!(mutation,LayoutMutation::CreateFrame(_)|LayoutMutation::DeleteFrame(_)|LayoutMutation::ChangeDataFields(_)|LayoutMutation::SetPageOverrides(_)|LayoutMutation::ReplaceDocument(_)){continue}let base:LayoutSnapshot=decode(row.get("before").unwrap_or(&extra["base"]));let original_base=base.clone();let original_mutation=mutation.clone();let mut owner=SimpleDecision::default();let mut done=false;for _ in 0..100000{let d=owner.demand();assert_eq!(owner.advance(&mutation,&base,Default::default()).unwrap().progress,Default::default());let step=owner.advance(&mutation,&base,grant(d)).unwrap();assert!(step.progress.fits(grant(d)));if step.done{assert_eq!(step.error.is_none()&&!step.unchanged,row["accepted"].as_bool().unwrap(),"{}",row["name"]);if let Some(error)=row.get("error"){assert_eq!(step.error,Some(error.as_str().unwrap()));}done=true;break}}assert!(done);assert_eq!(base,original_base);assert_eq!(mutation,original_mutation);owner.begin_close();while !owner.terminal_is_empty(){let d=owner.close_demand();let step=owner.close_step(grant(d));assert!(step.progress().fits(grant(d)))}checked+=1}assert_eq!(checked,169)}

#[test]
fn unicode_whitespace_and_long_names_use_bounded_native_reads(){let extra:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in extra["strings"].as_array().unwrap(){let base:LayoutSnapshot=decode(&extra["base"]);let mutation=LayoutMutation::UpdateSpread(crate::update_spread::UpdateSpread{id:base.spreads[0].id.clone(),name:row["value"].as_str().unwrap().into()});let mut owner=SimpleDecision::default();loop{let step=owner.advance(&mutation,&base,grant(owner.demand())).unwrap();if step.done{assert_eq!(step.error.is_none()&&!step.unchanged,row["admitted"].as_bool().unwrap());break}}owner.begin_close();while !owner.terminal_is_empty(){owner.close_step(grant(owner.close_demand()));}}let mut base:LayoutSnapshot=decode(&extra["base"]);base.name=format!("{}a","世界🌍".repeat(10000));let mutation=LayoutMutation::RenameLayout(crate::rename_layout::RenameLayout{new_name:format!("{}b","世界🌍".repeat(10000))});let mut owner=SimpleDecision::default();let mut turns=0;loop{let step=owner.advance(&mutation,&base,grant(owner.demand())).unwrap();turns+=1;if step.done{assert!(!step.unchanged&&step.error.is_none());break}assert!(turns<100000)}assert!(turns>300);owner.begin_close();while !owner.terminal_is_empty(){owner.close_step(grant(owner.close_demand()));}}
